{
  "title": "Discussion on tax filing, domain buying, and app monetization",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing complications and workaround",
      "claims": [
        {
          "text": "P1 paid ~1000 UAH to correct a declaration after an inspector approved incorrectly for 1.5 years and was later reprimanded.",
          "evidence": [1]
        },
        {
          "text": "The main difficulty is not calculating the tax amount but checking each column and subtraction correctly.",
          "evidence": [8]
        },
        {
          "text": "The procedure typically takes about an hour with Excel, about one day per month.",
          "evidence": [5,6,7]
        },
        {
          "text": "The calculator P1 used works only with a hryvnia‑only FOP; otherwise transactions must be converted using the day's exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain buying discussion",
      "claims": [
        {
          "text": "P2 states they have not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "P4 doubts anyone will buy the domain, calling it a “sira shtuka”.",
          "evidence": [10]
        },
        {
          "text": "P4 also remarks that buying the domain isn’t a priority until there are at least ten paying users.",
          "evidence": [20]
        }
      ]
    },
    {
      "id": "app-monetization",
      "title": "Viability of a small‑scale app product",
      "claims": [
        {
          "text": "P1 outlines many drawbacks of web‑based products (low SEO, no passive ad revenue, harsh paywall, low conversion).",
          "evidence": [11]
        },
        {
          "text": "P1 shares a podcast insight: fast delivery (< 1 week), cross‑platform stack (Flutter), and copying popular ideas can work.",
          "evidence": [12]
        },
        {
          "text": "P4 argues the project is a “free vibcode” with no real value, only a password hidden in local storage.",
          "evidence": [30,31,32]
        },
        {
          "text": "P1 sarcastically suggests LinkedIn users could easily hack the app.",
          "evidence": [28]
        }
      ]
    },
    {
      "id": "source-code-password",
      "title": "Source code and password availability",
      "claims": [
        {
          "text": "P1 asks whether the source code can be found via search for the password.",
          "evidence": [21]
        },
        {
          "text": "P4 responds rhetorically, implying they did not pay 299 UAH for it.",
          "evidence": [22]
        },
        {
          "text": "P4 says the password is stored “in the bundle”.",
          "evidence": [23]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is the source code/password actually accessible, and if so, how can it be retrieved?",
      "evidence": [21,22,23,28]
    }
  ]
}
